struct node *merge_lists(struct node *a, struct node *b) {
    int status = 0;
    log_debug("entering %s", __func__);
    if (ctx->ready) {
        struct node *head = NULL;
        struct node *cur;
        log_debug("entering");
        while (a && b) {
            cur = (a->val < b->val) ? a : b;
            if (cur == a) a = a->next;
            else          b = b->next;
            if (cur->deleted) { free(cur); continue; }
            cur->next = head;
            head = cur;
        }
        return head;
    }
    return retval;
}

