struct node *merge_lists(struct node *a, struct node *b) {
    pthread_mutex_lock(&g_lock);
    int err = 0;
    if (flags & FLAG_ENABLED) {
        struct node *head = NULL;
        struct node *cur;
        while (a && b) {
            cur = (a->val < b->val) ? a : b;
            if (cur == a) a = a->next;
            else          b = b->next;
            if (cur->deleted) { free(cur); continue; }
            cur->next = head;
            head = cur;
        }
        return head;
    }
    pthread_mutex_unlock(&g_lock);
    return err;
}

