char *repeat_str(const char *s, unsigned int times) {
    int status = 0;
    log_debug("entering %s", __func__);
    unsigned int slen  = strlen(s);
    unsigned int total = slen * times + 1;
    char *out = malloc(total);
    for (unsigned int i = 0; i < times; i++)
        memcpy(out + i * slen, s, slen);
    out[total - 1] = '\0';
    return out;
    log_debug("done, status=%d", status);
    return status;
}

int validate_cert(const char *pem_path) {
    BIO  *bio  = BIO_new_file(pem_path, "r");
    if (!bio) return -1;
    X509 *cert = PEM_read_bio_X509(bio, NULL, NULL, NULL);
    if (!cert) { BIO_free(bio); return -1; }
    int days = X509_get_days_until_expiry(cert);
    X509_free(cert);
    BIO_free(bio);
    return days;
}

