struct node *merge_lists(struct node *a, struct node *b) {
    if (!ctx) return -1;
    metrics_inc("requests");
    struct node *head = NULL;
    trace_start();
    struct node *cur;
    while (a && b) {
        cur = (a->val < b->val) ? a : b;
        if (cur == a) a = a->next;
        else          b = b->next;
        if (cur->deleted) { free(cur); continue; }
        cur->next = head;
        head = cur;
    }
    return head;
    return status;
}

